using System.Reflection;
using System.Reflection.Metadata;
using System.Reflection.PortableExecutable;

namespace PaymentAuthorization.ArchitectureTest;

// Inspects compiled metadata, so it catches any type use, not just `using` lines.
public sealed class LayerRulesTests
{
    private const string Domain = "PaymentAuthorization.Domain";
    private const string Application = "PaymentAuthorization.Application";
    private const string Infrastructure = "PaymentAuthorization.Infrastructure";

    private static readonly string[] TechnicalNamespaces =
    [
        "System.IO", "System.Net", "System.Data", "System.Diagnostics.Process",
        "System.Security.Cryptography.X509Certificates", "Microsoft.Data", "Microsoft.EntityFrameworkCore",
    ];

    [Fact]
    public void Domain_depends_on_no_other_layer()
        => AssertNoForbiddenUse(Domain, [Application, Infrastructure], TechnicalNamespaces);

    [Fact]
    public void Application_depends_only_on_Domain()
        => AssertNoForbiddenUse(Application, [Infrastructure], TechnicalNamespaces);

    private static void AssertNoForbiddenUse(string layer, string[] forbiddenLayers, string[] forbiddenNamespaces)
    {
        var assembly = Assembly.Load(layer);
        using var stream = File.OpenRead(assembly.Location);
        using var pe = new PEReader(stream);
        var md = pe.GetMetadataReader();

        var violations = new List<string>();

        foreach (var handle in md.AssemblyReferences)
        {
            var name = md.GetString(md.GetAssemblyReference(handle).Name);
            if (forbiddenLayers.Contains(name))
                violations.Add($"assembly reference: {name}");
        }

        foreach (var handle in md.TypeReferences)
        {
            var type = md.GetTypeReference(handle);
            var ns = md.GetString(type.Namespace);
            var full = $"{ns}.{md.GetString(type.Name)}";
            if (forbiddenLayers.Any(l => ns == l || ns.StartsWith(l + "."))
                || forbiddenNamespaces.Any(f => ns == f || ns.StartsWith(f + ".")))
                violations.Add($"type reference: {full}");
        }

        Assert.True(violations.Count == 0,
            $"{layer} breaks the layer rules:{Environment.NewLine}{string.Join(Environment.NewLine, violations.Distinct())}");
    }
}
